CREATE TABLE IF NOT EXISTS LShufWork_BStat (TableName TEXT PRIMARY KEY, Ord INTEGER, HasTarget INTEGER, W INTEGER, Start INTEGER, NT INTEGER, LLo INTEGER, LHi INTEGER, CLo INTEGER, CHi INTEGER);
DELETE FROM LShufWork_BStat;
INSERT INTO LShufWork_BStat (TableName, Ord, HasTarget) SELECT 'StartBiasBiomes', 0, 1 UNION ALL SELECT 'StartBiasTerrains', 1, 1 UNION ALL SELECT 'StartBiasAdjacentToCoasts', 2, 0 UNION ALL SELECT 'StartBiasFeatureClasses', 3, 1 UNION ALL SELECT 'StartBiasRivers', 4, 0 UNION ALL SELECT 'StartBiasLakes', 5, 0 UNION ALL SELECT 'StartBiasNaturalWonders', 6, 0 UNION ALL SELECT 'StartBiasIslands', 7, 0 UNION ALL SELECT 'StartBiasResources', 8, 1;
UPDATE LShufWork_BStat SET W = (SELECT COUNT(*) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName),
  NT = CASE WHEN HasTarget = 1 THEN (SELECT COUNT(DISTINCT r.TargetType) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.TargetType IS NOT NULL) ELSE 0 END,
  LLo = COALESCE((SELECT MIN(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NOT NULL), (SELECT MIN(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName)),
  LHi = COALESCE((SELECT MAX(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NOT NULL), (SELECT MAX(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName)),
  CLo = COALESCE((SELECT MIN(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NULL AND r.CivilizationType IS NOT NULL), (SELECT MIN(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName)),
  CHi = COALESCE((SELECT MAX(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NULL AND r.CivilizationType IS NOT NULL), (SELECT MAX(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName));
UPDATE LShufWork_BStat SET Start = COALESCE((SELECT SUM(o.W) FROM LShufWork_BStat o WHERE o.Ord < LShufWork_BStat.Ord), 0);
CREATE TABLE IF NOT EXISTS LShufWork_BTarget (TableName TEXT, TargetType TEXT, Rank INTEGER, PRIMARY KEY (TableName, TargetType));
DELETE FROM LShufWork_BTarget;
INSERT INTO LShufWork_BTarget (TableName, TargetType) SELECT DISTINCT r.TableName, r.TargetType FROM LShufWork_BRow r
  JOIN LShufWork_BStat b ON b.TableName = r.TableName AND b.HasTarget = 1 WHERE r.TargetType IS NOT NULL;
UPDATE LShufWork_BTarget SET Rank = (SELECT COUNT(*) FROM LShufWork_BTarget o WHERE o.TableName = LShufWork_BTarget.TableName AND (o.TargetType < LShufWork_BTarget.TargetType)) WHERE 1 = 1;
CREATE TABLE IF NOT EXISTS LShufWork_BShape (Total INTEGER, LWith INTEGER, L2 INTEGER, CWith INTEGER, C2 INTEGER, CivCount INTEGER);
DELETE FROM LShufWork_BShape;
INSERT INTO LShufWork_BShape SELECT (SELECT COUNT(*) FROM LShufWork_BRow),
  (SELECT COUNT(DISTINCT LeaderType) FROM LShufWork_BRow WHERE LeaderType IS NOT NULL),
  (SELECT COUNT(*) FROM (SELECT LeaderType FROM LShufWork_BRow WHERE LeaderType IS NOT NULL GROUP BY LeaderType HAVING COUNT(*) >= 2)),
  (SELECT COUNT(DISTINCT CivilizationType) FROM LShufWork_BRow WHERE LeaderType IS NULL AND CivilizationType IS NOT NULL),
  (SELECT COUNT(*) FROM (SELECT CivilizationType FROM LShufWork_BRow WHERE LeaderType IS NULL AND CivilizationType IS NOT NULL
    GROUP BY CivilizationType HAVING COUNT(*) >= 2)),
  (SELECT COUNT(*) FROM LShufWork_Civ);

